import ICON_DARK from './brand/balancia/balancia-icon-dark.svg?no-inline';
import ICON_WHITE from './brand/balancia/balancia-icon-white.svg?no-inline';
import ICON_LIGHT from './brand/balancia/balancia-icon.svg?no-inline';
import LOCKUP_DARK from './brand/balancia/balancia-logo-dark.svg?no-inline';
import LOCKUP_WHITE from './brand/balancia/balancia-logo-white.svg?no-inline';
import LOCKUP_LIGHT from './brand/balancia/balancia-logo.svg?no-inline';

/*
 * Balancia's mark (brand/logo/, generated by brand/build.py — copy, never redraw): the lockup for
 * `full`, the icon alone for `min`, in the version that matches the ground (brand/SYSTEM.md §5):
 * `light` on a light ground, `dark` on a dark one, `white` on teal. `?no-inline` always emits a real
 * file (celer-09: a data URI of an SVG can fail to decode with no error).
 */
const BALANCIA_LOGO = {
  full: { dark: LOCKUP_DARK, light: LOCKUP_LIGHT, white: LOCKUP_WHITE },
  min: { dark: ICON_DARK, light: ICON_LIGHT, white: ICON_WHITE },
} as const;

/** The wordmark's own text: the `alt` of the picture that draws it. */
const BALANCIA_NAME = 'Balancia';

export { BALANCIA_LOGO, BALANCIA_NAME };
